import {blank,entry} from './model.js';
export function vox(){const c=blank();Object.assign(c,{name:'VOX',species:'Tiefling',className:'Druid',subclass:'Circle of Wildfire',level:5,maxHp:38,hp:38,acBase:11,shield:2,speed:30,abilities:{str:8,dex:14,con:14,int:10,wis:18,cha:12},saves:['int','wis'],skills:{'Animal Handling':1,Nature:1,Perception:1,Survival:1},skillBonuses:{Arcana:4,Nature:4},slots:[4,3,2,0,0,0,0,0,0],gold:94,silver:17,copper:6,proficiencies:'Light armor, shields, simple weapons, herbalism kit. Common, Druidic; choose additional languages and background proficiencies with your DM.',contacts:'Maelis Emberroot — travelling herbalist; trades rare plants and news of blighted forests.\nCaptain Ilyra Fen — caravan guard; passage and escort work.\nThorn Ashvale — shrine keeper; wildfire spirits and druidic symbols.\nVerrick Sable — relic dealer; occasional buyer of curiosities.\n\nOptional connections from the supplied sheet; no player backstory imposed.',notes:'Preset follows the supplied VOX sheet: 2024 Druid with an adapted Circle of Wildfire. Background, species legacy and Magician choice remain provisional. Review spell versions and subclass compatibility with your DM. This is a configurable tracker, not a complete rules validator.\n\nMagician bonus to Arcana and Nature is entered as +4 in Builder → Skills. Update it when Wisdom changes or remove it if you choose Warden.'});
 c.attacks=[['Produce Flame','wis',true,0,'2d8','Fire','30 ft.'],['Primal Savagery','wis',true,0,'2d10','Acid','Melee'],['Sickle','str',true,0,'1d4+@mod','Slashing','Melee'],['Scimitar','dex',false,0,'1d6+@mod','Slashing','Melee'],['Quarterstaff','str',true,0,'1d6+@mod','Bludgeoning','Melee']].map(([name,ability,proficient,bonus,damage,damageType,range])=>({...entry('attacks'),name,ability,proficient,bonus,damage,damageType,range,spellAttack:['Produce Flame','Primal Savagery'].includes(name),description:name==='Scimitar'?'Not proficient under the supplied Magician choice; enable proficiency if trained.':name==='Sickle'?'The Moon Sickle can replace this attack. Set magic bonus +1 and damage 1d4+@mod+1 while using it.':name==='Quarterstaff'?'Versatile: use 1d8+@mod when wielded in two hands.':'Spell attack: use the Spell Attack button if magical gear changes your spell bonus.'}));
 const spellData=[
 ['Produce Flame',0,'attack','2d8','Fire','Create a flame; use a ranged spell attack to throw it. Check the casting action for your selected rules version.'],
 ['Guidance',0,'none','1d4','','Aid an ability check with a d4; check timing and duration for your chosen version.'],
 ['Primal Savagery',0,'attack','2d10','Acid','A melee spell attack using transformed claws or teeth.'],
 ['Thorn Whip',0,'attack','2d6','Piercing','Melee spell attack with extended reach; can pull a qualifying creature closer.'],
 ['Thaumaturgy',0,'none','','','Minor supernatural signs and sensory effects.'],
 ['Burning Hands',1,'damage','3d6','Fire','A cone of flame; Dexterity save. Enter any upcast dice in the roller.'],
 ['Cure Wounds',1,'heal','2d8+@spell','','Touch healing; formula uses the 2024 version. Use 1d8+@spell for the 2014 version.'],
 ['Speak with Animals',1,'none','','','Communicate with beasts. Ritual; always prepared by Druidic in this build.'],
 ['Healing Word',1,'heal','2d4+@spell','','Ranged bonus-action healing; formula uses 2024. Use 1d4+@spell for 2014.'],
 ['Entangle',1,'none','','','Conjure grasping plants; Strength save, difficult terrain and restraint. Concentration.'],
 ['Faerie Fire',1,'none','','','Illuminate targets in an area; Dexterity save. Outlined targets are easier to attack. Concentration.'],
 ['Goodberry',1,'none','','','Create nourishing berries with limited healing. Track berries as an inventory item.'],
 ['Flaming Sphere',2,'damage','2d6','Fire','Move a burning sphere; Dexterity saves. Concentration.'],
 ['Scorching Ray',2,'attack','2d6','Fire','Roll a spell attack for each ray and damage for each hit; the listed formula is per ray.'],
 ['Moonbeam',2,'damage','2d10','Radiant','A cylinder of light; Constitution saves. Concentration.'],
 ['Pass without Trace',2,'none','','','Group stealth assistance. Concentration.'],
 ['Spike Growth',2,'damage','2d4','Piercing','Hidden, difficult terrain; damage for each qualifying movement increment. Concentration.'],
 ['Plant Growth',3,'none','','','Thicken vegetation or enrich an area for agriculture, depending on casting time.'],
 ['Revivify',3,'none','','','Return a recently dead creature to life; requires a consumed costly diamond component. Verify timing and components.'],
 ['Dispel Magic',3,'none','','','End qualifying spells; a spellcasting ability check may be needed for higher-level effects.'],
 ['Call Lightning',3,'damage','3d10','Lightning','Call repeated bolts from a storm cloud; Dexterity saves. Concentration.']];
 const always=['Burning Hands','Cure Wounds','Speak with Animals','Flaming Sphere','Scorching Ray','Plant Growth','Revivify'];
 c.spells=spellData.map(([name,level,rollKind,roll,damageType,description])=>({...entry('spells'),name,level,rollKind,roll,damageType,description,always:always.includes(name),prepared:true,concentration:/Concentration/.test(description),ritual:name==='Speak with Animals',castingTime:name==='Healing Word'?'Bonus action':'Check spell version'}));
 c.items=[{...entry('items'),name:'Moon Sickle +1',description:'Druid focus. While held: +1 spell attacks and spell save DC. Healing spells can add 1d4. To use as a weapon, update the Sickle attack in Builder. Suggested reward from the supplied sheet; DM approval required.',requiresAttunement:true,attuned:true,spellAttack:1,spellDc:1,roll:'1d4'},{...entry('items'),name:'Cloak of Protection',description:'+1 AC and +1 to all saves while worn and attuned. When transforming, decide with your DM whether it remains worn or merges; toggle equipped accordingly.',requiresAttunement:true,attuned:true,ac:1,saves:1}];
 ['Leather armor','Wooden shield','Scimitar','Quarterstaff','Druidic focus',"Explorer’s pack",'Bedroll','Waterskin','Hemp rope (50 ft.)','Tinderbox','Torches','Rations (days)','Herbalism kit','Travel cloak','Glass vial of black volcanic sand','Charred brass compass','Spiral-carved river stone','Copper leaf pendant','Half-burnt trail map'].forEach(name=>c.items.push({...entry('items'),name,quantity:name==='Torches'?10:name==='Rations (days)'?7:1,description:'From the supplied VOX inventory. Armor and shield are already included in the base AC calculation; do not add their AC twice.'}));
 c.features=[['War Caster','Advantage on Constitution saves to maintain concentration; perform somatic components with hands full; Reactive Spell under the feat’s conditions. The selected ability increase is already included in this preset.'],['Wild Shape','2024 source-sheet convention: bonus action; spend one Wild Shape use; gain 5 temporary HP at this level; 2-hour duration. Physical abilities change; mental abilities remain. No spellcasting while transformed. The Forms tab automates physical abilities, AC, speed, temporary HP, and resource spending. Check equipment and beast skill bonuses manually.'],['Wild Companion','Use a spell slot or Wild Shape use for Find Familiar under the class feature. Record the spent resource manually.'],['Wild Resurgence','When no Wild Shape uses remain, a spell slot can restore one use; a Wild Shape use can restore a level 1 slot once per long rest. Adjust the trackers and mark the daily resource.'],['Druidic / Magician','Druidic language; Speak with Animals always prepared. Magician is provisional: additional druid cantrip and Wisdom bonus to Arcana and Nature.'],['Tiefling','Darkvision; Otherworldly Presence / Thaumaturgy. Select Fiendish Legacy with your DM; do not assume unchosen resistances or spells.'],['Wildfire Spirit','Spend a Wild Shape use to summon. Supplied level-5 statistics: AC 13, HP 30, speed 30 ft., fly 30 ft. hover. Summoning: 2d6 fire on a failed Dexterity save. Flame Seed: spell attack, 1d6+3 fire. Fiery Teleportation: 1d6+3 fire on a failed save. Acts after your turn; bonus action to command. Track spirit HP separately.']].map(([name,description])=>({...entry('features'),name,description}));
 c.resources=[{...entry('resources'),name:'Wild Shape',max:2,reset:'long',shortAmount:1},{...entry('resources'),name:'Wild Resurgence slot recovery',max:1,reset:'long'},{...entry('resources'),name:'Wildfire Spirit HP',max:30,reset:'none',description:'Remaining points show current spirit HP. Restore manually when summoned.'}];
 c.forms=[['Wolf',12,15,12,13,40,[['Bite',4,'1d6+2']],'Keen Hearing and Smell; Pack Tactics. Bite can knock prone (DC 11 Strength). Perception +3; Stealth +4.'],['Panther',14,15,10,12,50,[['Bite',4,'1d6+2'],['Claw',4,'1d4+2']],'Climb 40 ft. Keen Smell; Pounce after moving 20 ft. and hitting with claw (DC 12 Strength). Perception +4; Stealth +6.'],['Black Bear',15,10,14,11,40,[['Bite',3,'1d6+2'],['Claw',3,'2d4+2']],'Climb 30 ft. Keen Smell; multiattack. Perception +3.'],['Crocodile',15,10,13,12,20,[['Bite',4,'1d10+2']],'Swim 30 ft. Hold Breath. Bite grapples and restrains; escape DC 12. Stealth +2.'],['Giant Badger',13,10,15,10,30,[['Bite',3,'1d6+1'],['Claw',3,'2d4+1']],'Burrow 10 ft. Darkvision 30 ft.; Keen Smell; multiattack. Perception +3.'],['Riding Horse',16,10,12,10,60,[['Hooves',5,'2d4+3']],'Fast travel; carries a rider or pack load.']].map(([name,str,dex,con,ac,speed,attacks,description])=>({...entry('forms'),name,str,dex,con,ac,speed,tempHp:5,description:'SRD 5.1 form from the supplied sheet; verify with your DM. '+description,attacks:attacks.map(([name,bonus,damage])=>({name,bonus,damage}))}));
 return c;}
